<div class="page-title"><div><h2>مدیریت مدال‌ها</h2><p class="text-muted">تعریف مدال‌ها حذف فیزیکی نمی‌شود تا تاریخچه کاربران باقی بماند.</p></div></div>
<section class="card"><div class="card-header"><h3>افزودن یا ویرایش تعریف مدال</h3></div><form method="post" action="<?= e(url('medals/store')) ?>" class="form-grid three"><?= csrf_field() ?><label>شناسه انگلیسی<input name="slug" required pattern="[A-Za-z0-9_-]+" placeholder="first-contract"></label><label>عنوان<input name="title" required></label><label>امتیاز<input name="points" inputmode="numeric" value="0"></label><label>آیکن Feather<input name="icon_key" value="award"></label><label>رنگ<input name="color" type="color" value="#f59e0b"></label><label>دسته<select name="category"><option value="payment">پرداخت</option><option value="loyalty">وفاداری</option><option value="early_payment">پرداخت زودهنگام</option><option value="settlement">تسویه</option><option value="contract">قرارداد</option><option value="activity">فعالیت</option><option value="special">ویژه</option><option value="manual">دستی</option></select></label><label>نوع معیار<input name="criteria_type" placeholder="contract_count"></label><label>JSON معیار<input name="criteria_json" value='{"minimum":1}' dir="ltr"></label><label>ترتیب<input name="sort_order" value="0" inputmode="numeric"></label><label class="full">توضیح کوتاه<input name="short_description"></label><label class="full">روش دریافت<textarea name="how_to_earn" rows="2"></textarea></label><label class="check"><input type="checkbox" name="is_active" value="1" checked><span>فعال</span></label><div class="full"><button class="btn btn-primary" type="submit">ذخیره تعریف</button></div></form></section>
<section class="card"><div class="table-responsive"><table class="table"><thead><tr><th>مدال</th><th>معیار</th><th>امتیاز</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach (($definitions ?? []) as $definition): ?><tr><td><i data-feather="<?= e($definition['icon_key']) ?>"></i> <?= e($definition['title']) ?><br><small dir="ltr"><?= e($definition['slug']) ?></small></td><td><?= e($definition['criteria_type'] ?: '-') ?><br><small><?= e($definition['how_to_earn'] ?: '') ?></small></td><td><?= to_persian_digits($definition['points']) ?></td><td><?= !empty($definition['is_active']) ? 'فعال' : 'غیرفعال' ?></td><td><?php if (!empty($definition['is_active'])): ?><span class="badge info">قابل اعطا</span><?php endif; ?></td></tr><?php endforeach; ?><?php if (empty($definitions)): ?><tr><td colspan="5" class="empty">تعریفی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div></section>
